#!/usr/bin/env node
/**
 * Builds one SQL script that applies every migration in supabase/migrations that the target
 * database has not recorded yet — for pasting into the Supabase SQL Editor when the CLI
 * (`supabase db push`, the "Database migrations" workflow) is not an option.
 *
 * Each migration runs only if its version is missing from supabase_migrations.schema_migrations and
 * is then recorded there, exactly as the CLI would, so `db push` keeps working afterwards. The
 * editor sends the script as one statement batch, which PostgreSQL runs in a single transaction: if
 * any migration fails, nothing is changed.
 *
 *   node scripts/build-migration-bundle.mjs > migrations-bundle.sql
 */
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dirname, "..", "supabase", "migrations");
const files = readdirSync(dir)
  .filter((f) => /^\d{14}_.+\.sql$/.test(f))
  .sort();

const out = [
  "-- TuneWick: pending migrations (generated by scripts/build-migration-bundle.mjs).",
  "-- Paste everything into Supabase → SQL Editor and press Run. Safe to run more than once.",
  "",
  "create schema if not exists supabase_migrations;",
  "create table if not exists supabase_migrations.schema_migrations (version text primary key, statements text[], name text);",
  "",
  // A database that has the schema but no record of it was set up by hand; running everything
  // again would fail half-way, so stop before touching anything.
  "do $guard$ begin",
  "  if to_regclass('public.artists') is not null",
  "     and not exists (select 1 from supabase_migrations.schema_migrations) then",
  "    raise exception 'TuneWick tables exist but no migrations are recorded - send this message to the developer; nothing was changed.';",
  "  end if;",
  "end $guard$;",
  "",
];

for (const file of files) {
  const version = file.slice(0, 14);
  const name = file.slice(15, -4);
  const sql = readFileSync(join(dir, file), "utf8");
  const tag = `$tw_${version}$`;
  if (sql.includes(tag)) throw new Error(`${file} contains ${tag}`);
  out.push(
    `-- ${file}`,
    `do $run$ begin`,
    `  if not exists (select 1 from supabase_migrations.schema_migrations where version = '${version}') then`,
    `    execute ${tag}${sql}${tag};`,
    `    insert into supabase_migrations.schema_migrations (version, name) values ('${version}', '${name}');`,
    `    raise notice 'applied ${file}';`,
    `  end if;`,
    `end $run$;`,
    "",
  );
}

out.push(
  "select version, name from supabase_migrations.schema_migrations order by version desc limit 5;",
);
process.stdout.write(out.join("\n") + "\n");
